#!/usr/bin/env bash
# Engine comparison on the same 4 RTX VM: starts a server (vLLM of R1 or SGLang), applies the
# correctness gate and measures speed and agent sessions within the SLO (docs/03-serving-engine-and-benchmarks.md).
# LAUNCH_MODE=docker (default; VM with Docker) or LAUNCH_MODE=direct (instance that already is the
# image's container, as on Vast.ai; vLLM uses server-vllm-direct.sh, generated by docker_to_direct.py).
# Usage:
#   ENGINE=vllm   IMAGE=ghcr.io/local-inference-lab/vllm:<tag> SERVER_SCRIPT=server-vllm.sh   bash run_benchmark.sh
#   ENGINE=sglang IMAGE=<sglang image>                         SERVER_SCRIPT=server-sglang.sh bash run_benchmark.sh
# Then: python3 summarize.py --price 7.20 results/<date>-vllm results/<date>-sglang
# Prerequisite: llm-inference-bench with bench-exact-history-sglang.patch (exact agent history on
# SGLang), installed by setup_bench.sh. Without it SGLang is measured with random replies and loses cache.
set -euo pipefail
cd "$(dirname "$0")"
ENGINE=${ENGINE:?set ENGINE=vllm or ENGINE=sglang}
IMAGE=${IMAGE:?set IMAGE}
SERVER_SCRIPT=${SERVER_SCRIPT:?set SERVER_SCRIPT (script that starts the server)}
GPUS=${GPUS:-0,1,2,3}
PORT=${PORT:-8000}
NAME=${NAME:-glm53-cmp-$ENGINE}
BENCH=${BENCH:-${BENCH_DIR:-llm-inference-bench}/llm_decode_bench.py}
PY=${PY:-python3}
READY_TIMEOUT=${READY_TIMEOUT:-3600}
# Levels "agents:seconds". Above 32 both engines only queue (vLLM of R1: --max-num-seqs 32;
# ormandj SGLang: 16). Each level lasts the cold phase (all first turns of 40K to 100K tokens
# queue together, about 25 s per agent measured on Vast) plus about 7 min of steady state.
AGENT_LEVELS=${AGENT_LEVELS-8:600 16:900 32:1500}
AGENTS_ONLY=${AGENTS_ONLY:-0}   # 1 = skip gate and speed (already measured with the same server)
AGENT_START=${AGENT_START:-40k-100k}
AGENT_TOOL=${AGENT_TOOL:-1k-6k}
AGENT_RESPONSE=${AGENT_RESPONSE:-300-4000}
AGENT_THINK=${AGENT_THINK:-0-3}
STOP_ON_GATE_FAIL=${STOP_ON_GATE_FAIL:-1}
LAUNCH_MODE=${LAUNCH_MODE:-docker}
OUT=${OUT:-results/$(date +%Y%m%d-%H%M)-$ENGINE}
case "$ENGINE" in vllm|sglang) ;; *) echo "invalid ENGINE: $ENGINE"; exit 1 ;; esac
case "$LAUNCH_MODE" in docker|direct) ;; *) echo "invalid LAUNCH_MODE: $LAUNCH_MODE"; exit 1 ;; esac
[ -f "$SERVER_SCRIPT" ] || { echo "SERVER_SCRIPT does not exist: $SERVER_SCRIPT"; exit 1; }
[ -f "$BENCH" ] || { echo "bench not found at $BENCH: run setup_bench.sh or set BENCH"; exit 1; }
grep -q 'return_token_ids' "$BENCH" || { echo "the bench at $BENCH lacks the SGLang exact-history patch"; exit 1; }
mkdir -p "$OUT"
echo "$ENGINE" > "$OUT/engine.txt"
cp "$SERVER_SCRIPT" "$OUT/server.sh"

# 1) host state
{ echo "== date: $(date -Is) engine: $ENGINE image: $IMAGE"
  nvidia-smi --query-gpu=index,name,driver_version,persistence_mode,power.limit,clocks.max.sm,pcie.link.gen.current,pcie.link.width.current --format=csv
  echo "== RegistryDwords:"; grep -i RegistryDwords /proc/driver/nvidia/params || echo "(empty)"
  nvidia-smi topo -m; } > "$OUT/host.txt" 2>&1

# 2) server, with a wait loop that detects failure (error patterns of both engines)
PIDFILE=$OUT/server.pid
LOGFILE=$OUT/server-direct.log
collect_log() {
  if [ "$LAUNCH_MODE" = docker ]; then docker logs "$NAME" > "$OUT/server.log" 2>&1 || true
  else cp "$LOGFILE" "$OUT/server.log" 2>/dev/null || true; fi
}
server_state() {
  if [ "$LAUNCH_MODE" = docker ]; then docker inspect -f '{{.State.Status}}' "$NAME" 2>/dev/null || echo missing
  elif kill -0 "$(cat "$PIDFILE" 2>/dev/null)" 2>/dev/null; then echo running
  else echo dead; fi
}
stop_server() {
  if [ "$LAUNCH_MODE" = docker ]; then docker stop "$NAME" >/dev/null 2>&1 || true
  else kill "$(cat "$PIDFILE")" 2>/dev/null || true; fi
}
[ "$LAUNCH_MODE" = docker ] && { docker rm -f "$NAME" >/dev/null 2>&1 || true; }
NAME=$NAME GPUS=$GPUS PORT=$PORT IMAGE=$IMAGE LAUNCH_MODE=$LAUNCH_MODE PIDFILE=$PIDFILE LOGFILE=$LOGFILE \
  bash "$OUT/server.sh" > "$OUT/server-id.txt"
trap stop_server EXIT
start=$(date +%s)
while true; do
  collect_log
  state=$(server_state)
  if [ "$state" != "running" ]; then echo "FAILURE: server $state"; tail -40 "$OUT/server.log"; exit 2; fi
  if grep -qE "Traceback|CUDA out of memory|OutOfMemoryError|Engine core initialization failed|Scheduler hit an exception|Received sigquit" "$OUT/server.log"; then
    echo "FAILURE: error in log"; grep -nE "Traceback|OutOfMemory|Engine core|Scheduler hit|sigquit|Error" "$OUT/server.log" | head -20; exit 3; fi
  if curl -sf "http://localhost:$PORT/v1/models" >/dev/null 2>&1; then break; fi
  if [ $(( $(date +%s) - start )) -gt "$READY_TIMEOUT" ]; then echo "FAILURE: timeout of $READY_TIMEOUT s"; exit 4; fi
  sleep 10
done
echo "ready in $(( $(date +%s) - start )) s" | tee "$OUT/ready-time.txt"
curl -sf "http://localhost:$PORT/get_server_info" > "$OUT/server-info.json" 2>/dev/null || true

if [ "$AGENTS_ONLY" != 1 ]; then
# 3) correctness gate first: if it fails, the speed measurements are not worth the money
"$PY" "$BENCH" --port "$PORT" --test-profile needle-checksum --profile-runs "${NEEDLE_RUNS:-500}" --profile-concurrency 8 --output "$OUT/needle.json" > "$OUT/needle.log" 2>&1
# at 16 concurrent requests the batch fills the largest decode CUDA graph, where SGLang's EAGLE NaN (#49881) shows up
"$PY" "$BENCH" --port "$PORT" --test-profile needle-checksum --profile-runs 120 --profile-concurrency 16 --output "$OUT/needle-c16.json" > "$OUT/needle-c16.log" 2>&1
"$PY" "$BENCH" --port "$PORT" --test-profile gsm8k --profile-runs 96 --profile-concurrency 8 --output "$OUT/gsm8k.json" > "$OUT/gsm8k.log" 2>&1
# same verdict as summarize.py: one-sided Fisher against the reference (NEEDLE_REF, default 3/500), not "zero errors"
needle_ok=$("$PY" -c "import json,summarize;ref=summarize.NeedleReference.from_text('${NEEDLE_REF:-3/500}');print(int(all(summarize.passes_needle(json.load(open(f)),ref) for f in ('$OUT/needle.json','$OUT/needle-c16.json'))))")
if [ "$needle_ok" != 1 ] && [ "$STOP_ON_GATE_FAIL" = 1 ]; then
  echo "FAIL on needle-checksum (see $OUT/needle.log and needle-c16.log); stopping before the measurements"; exit 5
fi
if [ "${GATE_ONLY:-0}" = 1 ]; then echo "OK: gate only in $OUT"; exit 0; fi

# 4) speed (same parameters as R1)
"$PY" "$BENCH" --port "$PORT" --concurrency 1,8,16,32 --contexts 0 --duration 30 --max-tokens 8192 --skip-prefill --output "$OUT/decode.json" > "$OUT/decode.log" 2>&1
"$PY" "$BENCH" --port "$PORT" --prefill-only --standalone-prefill --prefill-contexts 8k,32k,128k,256k --output "$OUT/prefill.json" > "$OUT/prefill.log" 2>&1
fi

# 5) agents: one level at a time, each with its own seed so that no level inherits the previous one's cache
for level in $AGENT_LEVELS; do
  n=${level%%:*}; dur=${level#*:}
  [[ "$n" =~ ^[0-9]+$ && "$dur" =~ ^[0-9]+$ ]] || { echo "invalid level in AGENT_LEVELS: $level (use agents:seconds)"; exit 1; }
  "$PY" "$BENCH" --port "$PORT" --scheduler agents --sched-agents "$n" --sched-agents-duration "$dur" \
    --sched-agent-start "$AGENT_START" --sched-agent-tool "$AGENT_TOOL" \
    --sched-agent-response "$AGENT_RESPONSE" --sched-agent-think "$AGENT_THINK" \
    --sched-seed "$n" --output "$OUT/agents-$n.json" > "$OUT/agents-$n.log" 2>&1 || echo "agents-$n exited with code $? (see log)" >> "$OUT/warnings.txt"
done

collect_log
echo "OK: $OUT"
